bash: cd my_website && node -e "
const fs=require('fs');
const t=fs.readFileSync('.github/workflows/deploy.yml','utf8');
const lines=t.split('\n');
let err=[];
// tab check (YAML forbids tabs for indentation)
lines.forEach((l,i)=>{ if(/^\t/.test(l)) err.push('tab indent line '+(i+1)); });
// structural sanity: top-level keys
const top=lines.filter(l=>/^[A-Za-z_][A-Za-z0-9_-]*:/.test(l)).map(l=>l.split(':')[0]);
console.log('top-level keys:',top.join(', '));
// every 'uses:' must be a full 40-hex SHA pin
const uses=[...t.matchAll(/uses:\s*(\S+)@(\S+)/g)];
for(const [,a,r] of uses){
  const ok=/^[0-9a-f]{40}$/.test(r);
  console.log((ok?'PINNED  ':'MUTABLE ')+a+'@'+(ok?r.slice(0,12)+'…':r));
  if(!ok) err.push('unpinned action '+a);
}
// no pull_request_target / no script injection surface
if(/pull_request_target/.test(t)) err.push('pull_request_target present');
if(/\$\{\{\s*github\.event/.test(t)) err.push('raw event context interpolated into run:');
console.log(err.length? 'ERRORS: '+err.join('; ') : 'WORKFLOW VALID: no tabs, all actions SHA-pinned, no PR-target, no script-injection surface');
"

