bash: cd my_website/public && node -e "
const fs=require('fs');
// Minimal well-formedness check: tag balance for block elements + required head meta.
const files=['index.html','blog.html','publications.html','404.html',
 ...fs.readdirSync('posts').map(f=>'posts/'+f)];
let bad=0;
for(const f of files){
  const h=fs.readFileSync(f,'utf8');
  const issues=[];
  for(const tag of ['html','head','body','main','header','footer','nav','article','section','ul','ol','li','p','h1','h2','h3','dl','a','div']){
    const open=(h.match(new RegExp('<'+tag+'(?=[\\\\s>])','g'))||[]).length;
    const close=(h.match(new RegExp('</'+tag+'>','g'))||[]).length;
    if(open!==close) issues.push(tag+' '+open+'/'+close);
  }
  if(!/^<!DOCTYPE html>/i.test(h.trim())) issues.push('no doctype');
  if(!/<title>[^<]+<\/title>/.test(h)) issues.push('no title');
  if(!/name="viewport"/.test(h)) issues.push('no viewport');
  if(!/name="description"/.test(h)) issues.push('no description');
  if(/<h1/.test(h)!==true) issues.push('no h1');
  const h1=(h.match(/<h1/g)||[]).length; if(h1!==1) issues.push('h1 count='+h1);
  console.log((issues.length?'FAIL ':'ok   ')+f+(issues.length?' :: '+issues.join(', '):''));
  if(issues.length)bad++;
}
console.log(bad?bad+' pages with issues':'ALL '+files.length+' PAGES WELL-FORMED (balanced tags, 1 h1, doctype, title, viewport, description)');
"

